{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Peripherally administered BH4 elevated CSF BH4 within 90 minutes, providing direct evidence that a polar fused heteroaromatic can achieve CNS access after i.v. dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "MTX-241F, a structurally related aminopyrimidine-fused heteroaromatic inhibitor, achieved micromolar murine brain concentrations after systemic dosing, supporting CNS access for the query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "PhIP, an amino-substituted fused heteroaromatic, crosses the BBB after systemic administration, supporting CNS penetration for similar aminopyrimidine-containing heteroaromatics.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lorlatinib, a CNS-penetrant kinase inhibitor with an aminopyridine/ether/amide motif, showed a human CSF/plasma ratio of 0.75 and PET-confirmed brain uptake, demonstrating that this chemotype can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ribociclib, containing an aminopyrimidine and piperazine on a fused heteroaromatic core, was detected at clinically relevant CSF levels in patients, supporting CNS penetration for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "ETC-168, a morpholine amide-containing fused heteroaromatic, achieved a brain-to-plasma ratio of 0.12 and was classified as brain-penetrant in mice, supporting the query's CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Compound 6, a morpholine sulfonamide aminopyrimidine, showed a high rat brain/plasma ratio of 2.4, supporting that morpholine/aminopyrimidine combinations can be highly brain-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "CZC25146, a morpholine- and aminopyrimidine-containing compound, showed negligible mouse brain penetration, indicating that some analogues in this space can be efflux-limited; however, its additional sulfonamide/aniline features are not present in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass predicted. Multiple high-transfer analogues with aminopyrimidine/morpholine/fused-heteroaromatic scaffolds show direct CNS exposure (brain tissue, CSF/plasma, PET), and the single negative analogue contains additional sulfonamide/aniline features not present in the query.",
  "evidence_gaps": [
    "No direct brain/CSF measurement for the query molecule itself.",
    "Efflux transporter (P-gp/BCRP) profile of the query is not directly known; one negative analogue suggests possible transporter-mediated liability.",
    "Human CNS exposure data for the query are absent; extrapolation relies on structurally related clinical compounds."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

